  "description": "Persistent cross-session memory backed by Weaviate Engram. Stores each conversation turn and recalls relevant memories before the assistant answers.",
  "version": "1.1.0",
  "author": {
    "name": "Weaviate"
  },
  "homepage": "https://docs.weaviate.io/engram",
  "hooks": "./assistants/codex/hooks.json",
  "skills": "./skills/"
