"""Config from JSON files: ~/.engram/config.json (global) plus the current directory's
.engram.json. Holds scope `properties` (how each value resolves) and `search` (which
topics/properties to filter). No env vars, no shell quoting — structured config lives in files."""

import json
import os

# The global (user-owned) config. A ~/.engram/ dir rather than a bare dotfile keeps it extensible;
# it holds your defaults, overridden by the current directory's .engram.json.
USER_CONFIG_PATH = "~/.engram/config.json"


def user_config_path():
    return USER_CONFIG_PATH


def _read_json(path):
    """Read a JSON object from a file. Missing → {}. Malformed JSON raises with the file named, so
    the hook errors out clearly instead of silently ignoring a broken config."""
    try:
        with open(os.path.expanduser(path)) as f:
            data = json.load(f)
    except FileNotFoundError:
        return {}
    except json.JSONDecodeError as e:
        raise ValueError(f"invalid JSON in {path}: {e}") from e
    return data if isinstance(data, dict) else {}


def _config_chain(cwd):
    """Config in increasing-precedence order: the global user config, then the .engram.json in the
    current directory (cwd overrides the global defaults)."""
    return [user_config_path(), os.path.join(os.path.realpath(cwd), ".engram.json")]


def _contains_cmd(value):
    """True if a property value uses a {"cmd": ...} source anywhere (including inside a cascade).
    A cmd runs an arbitrary command, so it's refused from committed/local config."""
    if isinstance(value, dict):
        return "cmd" in value
    if isinstance(value, list):
        return any(_contains_cmd(el) for el in value)
    return False


def load_config(cwd):
    """Merge config from the global ~/.engram/config.json and the current directory's .engram.json
    (cwd overrides). `properties` merge key-wise; `search` takes the deepest defined block.

    `cmd` sources run an arbitrary command, so they're honored ONLY from the global config
    (user-owned) — a repo you clone must never run a command on your machine via a hook. Literals
    and `from` tokens (fixed built-in lookups, no arbitrary execution) are fine in a committed
    .engram.json. A `cmd` found in a local file is dropped and reported in `warnings`."""
    cfg = {"properties": {}, "search": {}, "warnings": []}
    for i, path in enumerate(_config_chain(cwd)):
        part = _read_json(path)
        is_global = i == 0  # first entry is the global config; the rest are local/committed
        props = part.get("properties")
        if isinstance(props, dict):
            # JSON shape carries the meaning: string = literal, {"from"|"cmd"} = dynamic source,
            # list = cascade. Only `cmd` is refused locally (it would execute on clone).
            for k, v in props.items():
                if v is None:
                    continue
                if isinstance(v, (dict, list)):
                    if not is_global and _contains_cmd(v):
                        cfg["warnings"].append(
                            f'properties.{k} in {path}: a "cmd" source is only allowed in '
                            "~/.engram/config.json — ignored (a cloned repo must not run commands)"
                        )
                        continue
                    cfg["properties"][k] = v
                else:
                    cfg["properties"][k] = str(v)
        if isinstance(part.get("search"), dict):
            cfg["search"] = part["search"]
    return cfg

"""Engram connection + identity: API key / base URL resolution, the SDK client, and the
REST helper. Fails open — callers exit 0 so a coding session is never broken."""

import json
import os
import subprocess
import urllib.request

from engram import EngramClient

from .client_origin import client_origin_header

DEFAULT_BASE = "https://api.engram.weaviate.io"

_PROFILES = (
    "~/.zshenv",
    "~/.zshrc",
    "~/.zprofile",
    "~/.bashrc",
    "~/.bash_profile",
    "~/.profile",
)


def _from_profile(var):
    """Extract `export VAR=value` from shell profiles. A GUI host (e.g. Claude Desktop)
    doesn't inherit exported shell env, so this recovers vars set only in a profile."""
    prefix = var + "="
    for path in _PROFILES:
        try:
            with open(os.path.expanduser(path)) as f:
                lines = f.readlines()
        except Exception:
            continue  # this profile doesn't exist / isn't readable — try the next
        for line in reversed(lines):
            s = line.strip()
            if s.startswith("export "):
                s = s[7:].strip()
            if not s.startswith(prefix):
                continue
            val = s[len(prefix) :].strip()
            if val[:1] in ("'", '"'):
                end = val.find(val[0], 1)
                val = val[1:end] if end > 0 else val[1:]
            else:
                val = val.split("#", 1)[0].strip()
            if val and not val.startswith("$"):
                return val
    return None


def _config(env_var):
    """Resolve config (first non-empty wins): exported env var → shell-profile extraction.
    The profile fallback recovers vars set only in a shell profile when the host (e.g. Claude
    Desktop) doesn't inherit exported shell env."""
    return os.environ.get(env_var) or _from_profile(env_var)


def engram_api_key():
    return _config("ENGRAM_API_KEY")


def engram_base_url():
    # Dev/override only. Env (or profile fallback) → default.
    return (
        os.environ.get("ENGRAM_BASE_URL")
        or _from_profile("ENGRAM_BASE_URL")
        or DEFAULT_BASE
    )


def get_user_id():
    """Stable identity for memory scoping. ENGRAM_USER_ID (env or shell profile), then git email.
    Returns None when neither is set — callers MUST NOT fall back to a shared id like $USER or
    "default": memories are tagged with this id in Engram permanently, so a non-unique id would
    commingle different people's memories with no way to un-mix them later."""
    uid = _config("ENGRAM_USER_ID")  # env or shell-profile fallback (like the API key)
    if uid:
        return uid
    try:
        out = subprocess.run(
            ["git", "config", "user.email"],
            capture_output=True,
            text=True,
            timeout=2,
        )
    except Exception:
        return None  # git missing / timed out → no identity; engram_warning reports it
    return out.stdout.strip() or None


# One value, because every call is a single quick request: the SDK applies this per HTTP request,
# and memories.add returns a run id as soon as the server accepts the work rather than waiting for
# the pipeline. Ten seconds is a ceiling for a slow network, and stays inside the 30s Claude Code
# caps UserPromptSubmit at, leaving room for the venv build on a cold first prompt.
DEFAULT_TIMEOUT = 10.0


def _timeout() -> float:
    override = _config("ENGRAM_TIMEOUT")
    if not override:
        return DEFAULT_TIMEOUT
    try:
        seconds = float(override)
    except ValueError:
        return DEFAULT_TIMEOUT
    # The SDK rejects a non-positive timeout, and get_client runs outside the hooks' try/except.
    return seconds if seconds > 0 else DEFAULT_TIMEOUT


def get_client(assistant: str = "claude") -> EngramClient | None:
    api_key = [REDACTED]
    if not api_key:
        return None
    return EngramClient(
        api_key=api_key,
        base_url=engram_base_url(),
        headers=client_origin_header(assistant),
        timeout=_timeout(),
    )


def engram_warning():
    """Plain-text reason the plugin can't reach Engram, or None if it looks usable. The search
    hook prefixes it and surfaces it through the UserPromptSubmit directive."""
    if not engram_api_key():
        return "API key not set — memory disabled this session."
    if not get_user_id():
        return "no stable identity — set git user.email or ENGRAM_USER_ID to enable memory (prevents mixing memories between users)."
    return None


def engram_get(path):
    """GET a JSON path from the Engram REST API and return the parsed JSON. Raises on any HTTP
    or network error — the caller resolving scope lets it propagate so the operation fails as a
    whole instead of continuing with a half-resolved scope."""
    base = engram_base_url().rstrip("/")
    req = urllib.request.Request(
        base + path,
        headers={
            "Authorization": f"Bearer {engram_api_key()}",
            **client_origin_header(),
        },
    )
    with urllib.request.urlopen(req, timeout=5) as resp:
        return json.load(resp)

"""The contract core.hooks is written against. Implementations live in assistants/."""

import json
import os
from abc import ABC, abstractmethod
from collections.abc import Iterator
from dataclasses import dataclass
from functools import lru_cache
from typing import Any


@dataclass
class InputData:
    """The hook payload under one set of names, whichever assistant sent it."""

    stop_hook_active: bool = False
    last_assistant_message: str = ""
    cwd: str = ""
    session_id: str = ""
    prompt: str = ""
    transcript_path: str = ""
    turn_id: str = ""


@dataclass
class TranscriptEntry:
    """A transcript line under one set of names, whichever assistant wrote it."""

    role: str
    text: str
    turn_id: str = ""
    origin: str = ""


@lru_cache(maxsize=2)
def _lines(transcript_path: str, mtime: int, size: int) -> tuple[str, ...]:
    """Keyed on the file's identity so a rewritten transcript is re-read. A turn walks the
    transcript more than once and these files reach tens of megabytes. Module-level because an
    lru_cache on a method would keep the instance alive."""
    try:
        with open(transcript_path, "r", errors="replace") as f:
            return tuple(f)
    except OSError:
        return ()


class Assistant(ABC):
    @property
    @abstractmethod
    def name(self) -> str: ...

    @property
    @abstractmethod
    def manifest_dir(self) -> str: ...

    @property
    @abstractmethod
    def data_dir_env(self) -> str:
        """The host's variable for the plugin's writable data dir."""

    # Exit code for a failed store. Claude Code turns 2 into a wake carrying our stderr, but Codex
    # reads it as "continue the turn, using stderr as the prompt", so an assistant has to opt in.
    STORE_FAILURE_EXIT: int = 0

    def data_dir(self) -> str:
        """No fallback on purpose: a guessed path diverges from the one with-venv.sh builds the
        venv in, and makes bugs untraceable."""
        path = os.environ.get(self.data_dir_env)
        if not path:
            raise RuntimeError(f"{self.data_dir_env} not set — the host provides the data dir")
        return path

    @abstractmethod
    def read_input(self) -> InputData:
        """The hook payload on stdin. Malformed JSON raises — a hook should never run on garbage
        input."""

    @abstractmethod
    def read_entry(self, raw: dict[str, Any]) -> TranscriptEntry | None:
        """One line of this assistant's transcript, or None for a line that holds no message."""

    def last_user_text(self, payload: InputData) -> str:
        """The most recent message a person sent, or "" when none can be read."""
        for entry in self.transcript(payload):
            if entry.role == "user" and entry.text:
                return entry.text
        return ""

    def is_automated(self, payload: InputData) -> bool:
        """Whether the assistant started this turn rather than a person. An assistant that
        records no provenance keeps this default: losing the skip beats dropping a real turn."""
        return False

    def transcript(self, payload: InputData) -> Iterator[TranscriptEntry]:
        """Transcript entries, newest first. Both assistants write JSONL; one that doesn't can
        override this. An unreadable file or line yields nothing rather than raising, because a
        hook must not break a session over a transcript it cannot parse."""
        if not payload.transcript_path:
            return
        try:
            stat = os.stat(payload.transcript_path)
        except OSError:
            return
        for line in reversed(_lines(payload.transcript_path, stat.st_mtime_ns, stat.st_size)):
            try:
                entry = self.read_entry(json.loads(line))
            except Exception:
                continue
            if entry is not None:
                yield entry

"""Scope resolution: turn the active scope's required properties into concrete values via
deterministic sources (no LLM inference). The requirements are read live from /v1/groups so
only the configured properties are ever sent."""

import json
import os
import subprocess

from .client import engram_get
from .config import load_config
from .util import git_repo

# Built-in defaults for well-known properties — applied only when the live schema lists them and
# the user didn't configure them. Any other property is the user's to map in .engram.json.
DEFAULT_SOURCES = {
    # cwd fallback when git-repo yields nothing: no git remote, or run from a non-repo (e.g. parent) dir
    "repo_name": [{"from": "git-repo"}, {"from": "cwd"}],
    "session_id": {"from": "session_id"},
}

# The built-in `from` tokens — kept in sync with _resolve_token; used to flag typos in config.
VALID_TOKENS = ("git-repo", "cwd", "session_id")


def _resolve_token(token, cwd, session_id):
    """Resolve a built-in source token (no arguments): "git-repo" (owner-scoped repo name from the
    remote, e.g. owner/repo), "cwd", or "session_id" (the last two from the hook payload). Unknown
    token → None."""
    if token == "git-repo":
        return git_repo(cwd)
    if token == "cwd":
        return cwd
    if token == "session_id":
        return session_id or None
    return None


def _resolve_element(el, cwd, session_id):
    """Resolve one value / cascade element to a value (or None). JSON shape decides, with no
    possible collision: a string is a literal (used verbatim); a {"from": <token>} object is a
    built-in source; a {"cmd": ["prog", "arg", ...]} object runs argv directly (no shell, so no
    quoting/splitting pitfalls)."""
    if isinstance(el, str):
        return el.strip() or None
    if isinstance(el, dict):
        if "cmd" in el:
            cmd = el["cmd"]
            if not isinstance(cmd, list) or not cmd:
                return None
            out = subprocess.run(
                [str(a) for a in cmd],
                cwd=cwd,
                capture_output=True,
                text=True,
                timeout=5,
            )
            return out.stdout.strip() or None
        if "from" in el:
            return _resolve_token(el["from"], cwd, session_id)
    return None


def _resolve_value(value, cwd, session_id):
    """Resolve a configured property value. A JSON array is a cascade — its elements (literals,
    {"from": ...} or {"cmd": ...}) are tried in order and the first non-empty wins; any other value
    is resolved as a single element. This array replaces the old `a|b` string: explicit, not
    parsed, and a bare-string element is unambiguously a literal fallback."""
    for el in value if isinstance(value, list) else [value]:
        try:
            val = _resolve_element(el, cwd, session_id)
        except Exception:
            val = None  # this element errored (e.g. a cmd timeout) → fall through to the next
        if val:
            return str(val).strip()
    return None


def scope_schema(data_dir):
    """The active group's write requirements, fetched from /v1/groups and cached. Only one group
    is supported, so we take the response's default group and pass nothing to the API. The cache
    stores the raw group payload plus the derived `properties` (UNION of every topic's
    scope_properties) and `user` (any topic user-scoped). No expiry — once written it's reused
    (the schema rarely changes); reinstall to refresh it. Raises if the fetch fails and no cache."""
    cache = os.path.join(data_dir, "scope-schema.json")
    try:
        with open(cache) as f:
            return json.load(f)
    except Exception:
        pass  # missing or corrupt cache → fall through and re-fetch (recovers it)

    data = engram_get("/v1/groups")  # raises on failure → propagates to the hook
    groups = data.get("groups") or []
    group = next(
        (g for g in groups if g.get("name") == "default"), groups[0] if groups else {}
    )
    topics = group.get("topics", [])
    user = any((t.get("scoping") or {}).get("user_scoped") for t in topics)
    props = []
    for t in topics:
        for p in (t.get("scoping") or {}).get("scope_properties") or []:
            if p not in props:
                props.append(p)
    schema = {"user": user, "properties": props, "raw": group}
    try:
        os.makedirs(os.path.dirname(cache), exist_ok=True)
        with open(cache, "w") as f:
            json.dump(schema, f)
    except Exception:
        pass  # best-effort cache; the schema is returned in-memory regardless
    return schema


def resolve_scope(cwd, session_id, data_dir):
    """Resolve the scope properties to attach to a memory. Config always wins and is always sent;
    the cached schema's ONLY job is to pick which built-in DEFAULT_SOURCES to infer for properties
    the user didn't configure — it does not gate, require, or limit anything. So a stale schema
    (e.g. after switching projects) can be fully overridden from .engram.json without reinstalling
    to refresh the cache. The server, not the local schema, is the authority on what a store needs.

    Returns (props, user_required, unmapped) — `unmapped` lists configured/inferred properties that
    didn't resolve to a value, so the user can fix the source."""
    configured = load_config(cwd).get("properties", {})
    schema = scope_schema(data_dir)
    # Schema → defaults only: infer a DEFAULT_SOURCE for each schema property the user left unset.
    defaults = {
        name: DEFAULT_SOURCES[name]
        for name in schema.get("properties", [])
        if name in DEFAULT_SOURCES and name not in configured
    }
    to_resolve = {**defaults, **configured}  # config overrides the inferred defaults
    props, unmapped = {}, []
    for name, value in to_resolve.items():
        val = _resolve_value(value, cwd, session_id)  # already a stripped string or None
        if val:
            props[name] = val
        else:
            unmapped.append(name)
    return props, bool(schema.get("user")), unmapped


def _element_warnings(label, el):
    """Structural problems in one property value / cascade element (recurses into cascades).
    A string is a literal (always fine); a dict must be {"from": token} or {"cmd": [args]}."""
    if isinstance(el, str):
        return []
    if isinstance(el, list):
        out = []
        for i, item in enumerate(el):
            out += _element_warnings(f"{label}[{i}]", item)
        return out
    if isinstance(el, dict):
        if "cmd" in el:
            cmd = el["cmd"]
            if not isinstance(cmd, list) or not cmd:
                return [f'{label}: "cmd" must be a non-empty array of arguments']
            return []
        if "from" in el:
            if el["from"] not in VALID_TOKENS:
                return [
                    f'{label}: unknown source {el["from"]!r} '
                    f'(valid: {", ".join(VALID_TOKENS)})'
                ]
            return []
        return [f'{label}: expected {{"from": ...}} or {{"cmd": [...]}} (keys: {list(el)})']
    return [f"{label}: must be a string, a source object, or an array"]


def config_warnings(cwd):
    """Human-readable structural problems in the configured `properties` — a wrong/renamed source
    key, an unknown token, a malformed cmd — so a typo'd config is surfaced instead of silently
    resolving to nothing. (Malformed JSON is caught earlier and fails loud with the file named; a
    dynamic source in a local file is dropped by load_config with its own warning.)"""
    props = load_config(cwd).get("properties", {})
    out = []
    for name, value in props.items():
        out += _element_warnings(f"properties.{name}", value)
    return out
